package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string           // PIC X len=1 = "N"
var WsTax decimal.Decimal      // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal      // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64              // PIC 9(3) len=3 = 0
var WsIncEd string             // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string             // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string             // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string           // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxRec TaxRec
var taxFile *os.File
var taxReader *bufio.Reader
var eofReached bool

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeScaled(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate toward zero to scale
	t := v.Truncate(int32(scale))
	shifted := t.Shift(int32(scale))
	// shifted should be integral
	// keep low-order digits that fit
	totalDigits := intDigits + scale
	// use decimal modulo to avoid int64 overflow for large totalDigits (but fits)
	mod := decimal.NewFromInt(pow10(totalDigits))
	// need positive modulo for negative numbers as well (COBOL keeps sign? not needed)
	// get low digits: shifted mod mod, preserving sign
	sign := 1
	if shifted.IsNegative() {
		sign = -1
		shifted = shifted.Abs()
	}
	low := shifted.Mod(mod)
	if sign == -1 {
		low = low.Neg()
	}
	return low.Shift(int32(-scale))
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.IndexByte(pic, '.')
	scale := 0
	if dotIdx != -1 {
		for i := dotIdx + 1; i < len(pic); i++ {
			c := pic[i]
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	intSlots := 0
	end := len(pic)
	if dotIdx != -1 {
		end = dotIdx
	}
	for i := 0; i < end; i++ {
		if pic[i] == '9' || pic[i] == 'Z' {
			intSlots++
		}
	}

	abs := val.Abs()
	absTrunc := abs.Truncate(int32(scale))
	intPart := absTrunc.Truncate(0)
	fracPart := absTrunc.Sub(intPart).Shift(int32(scale)).Truncate(0)

	intStr := intPart.StringFixed(0)
	if intStr == "" {
		intStr = "0"
	}
	// intStr may contain '-' should not happen for Abs
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	} else if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}

	fracStr := ""
	if scale > 0 {
		fip := fracPart.IntPart()
		if fip < 0 {
			fip = -fip
		}
		fracStr = fmt.Sprintf("%0*d", scale, fip)
		if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
	}

	out := make([]byte, len(pic))
	intPos := 0
	fracPos := 0
	for i := 0; i < len(pic); i++ {
		ch := pic[i]
		switch ch {
		case 'Z', '9':
			if dotIdx != -1 && i > dotIdx {
				if fracPos < len(fracStr) {
					out[i] = fracStr[fracPos]
				} else {
					out[i] = '0'
				}
				fracPos++
			} else {
				if intPos < len(intStr) {
					out[i] = intStr[intPos]
				} else {
					out[i] = '0'
				}
				intPos++
			}
		case ',', '.':
			out[i] = byte(ch)
		default:
			out[i] = byte(ch)
		}
	}
	// Z suppression on integer part
	endInt := len(pic)
	if dotIdx != -1 {
		endInt = dotIdx
	}
	suppressed := true
	for i := 0; i < endInt; i++ {
		pc := pic[i]
		if pc == 'Z' {
			if suppressed && out[i] == '0' {
				out[i] = ' '
			} else {
				suppressed = false
			}
		} else if pc == '9' {
			suppressed = false
		} else if pc == ',' {
			if suppressed {
				out[i] = ' '
			}
		}
	}
	// sign handling not needed (all positive)
	return string(out)
}

func parseIncomeField(s string) decimal.Decimal {
	// s length 8, digits only, implied V99
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// keep only digits (if spaces inside)
	// remove non-digit
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	// construct
	n, _ := decimal.NewFromString(digits)
	// Actually NewFromString interprets as integer
	// Use New with exponent -2
	// If digits has leading zeros, NewFromString handles
	// Use n.Shift(-2)
	return n.Shift(-2)
}

func readPara() {
	if eofReached {
		return
	}
	line, err := taxReader.ReadString('\n')
	if err != nil {
		// EOF or error: if we got some data without newline, handle
		if len(line) == 0 {
			WsEofFlag = "Y"
			eofReached = true
			return
		}
		// partial line treated as record
		// strip trailing \r\n already partly
	}
	// remove line endings
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	taxRec.TrId = line[0:5]
	incomeField := line[5:13]
	taxRec.TrIncome = parseIncomeField(incomeField)
}

func processPara() {
	// IF TR-INCOME <= 10000.00 COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
	lim1 := decimal.NewFromInt(10000)
	lim2 := decimal.NewFromInt(40000)
	rate10 := decimal.NewFromString("0.10")
	rate20 := decimal.NewFromString("0.20")
	rate30 := decimal.NewFromString("0.30")
	const1000 := decimal.NewFromInt(1000)
	const7000 := decimal.NewFromInt(7000)
	const10000 := decimal.NewFromInt(10000)
	const40000 := decimal.NewFromInt(40000)

	if taxRec.TrIncome.Cmp(lim1) <= 0 {
		v := taxRec.TrIncome.Mul(rate10)
		v = v.Round(2)
		WsTax = storeScaled(v, 7, 2)
	} else {
		if taxRec.TrIncome.Cmp(lim2) <= 0 {
			v := taxRec.TrIncome.Sub(const10000).Mul(rate20).Add(const1000)
			v = v.Round(2)
			WsTax = storeScaled(v, 7, 2)
		} else {
			v := taxRec.TrIncome.Sub(const40000).Mul(rate30).Add(const7000)
			v = v.Round(2)
			WsTax = storeScaled(v, 7, 2)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	wsNetRaw := taxRec.TrIncome.Sub(WsTax)
	wsNetRaw = wsNetRaw.Truncate(2)
	WsNet = storeScaled(wsNetRaw, 7, 2)

	// ADD WS-TAX TO WS-TOTAL-TAX
	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = storeScaled(WsTotalTax.Truncate(2), 9, 2)

	// ADD 1 TO WS-COUNT with overflow mod 1000
	WsCount = (WsCount + 1) % 1000

	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	readPara()
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.Zero
	WsNet = decimal.Zero
	WsTotalTax = decimal.Zero
	WsCount = 0

	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist treat as empty
		taxFile = nil
		taxReader = bufio.NewReader(strings.NewReader(""))
	} else {
		taxReader = bufio.NewReader(taxFile)
		defer taxFile.Close()
	}
	// MAIN-PARA
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	if taxFile != nil {
		taxFile.Close()
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// WS-COUNT is PIC 9(3) zero-padded
	wsCountStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", wsCountStr, WsTotalEd)
}

